import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";

// Create axios instance with auth header
const api = axios.create({
  baseURL: "http://localhost:8000",
});

// Add interceptor to include token in requests
api.interceptors.request.use((config) => {
  const token = localStorage.getItem("token");
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

function ProfilePage() {
  const navigate = useNavigate();
  const [profile, setProfile] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [message, setMessage] = useState("");

  // Check authentication on component mount
  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) {
      navigate("/login");
      return;
    }
    
    fetchProfile();
  }, [navigate]);

  const fetchProfile = async () => {
    setIsLoading(true);
    try {
      const res = await api.get("/profile");
      setProfile(res.data);
    } catch (err) {
      console.error("Error fetching profile:", err);
      if (err.response?.status === 401) {
        // Token expired or invalid
        localStorage.removeItem("token");
        navigate("/login");
      } else {
        setMessage("Error loading profile information.");
      }
    } finally {
      setIsLoading(false);
    }
  };

  const logout = () => {
    localStorage.removeItem("token");
    navigate("/login");
  };

  const goToEnhancedUpload = () => {
    navigate("/upload");
  };

  // Loading spinner component
  const LoadingSpinner = () => (
    <div className="modern-loading-spinner">
      <div className="spinner-ring"></div>
      <div className="spinner-text">Loading...</div>
    </div>
  );

  return (
    <div className="modern-profile-container">
      {/* Header Section */}
      <div className="profile-header-section">
        <div className="header-content">
          <h1 className="profile-title">Employee Dashboard</h1>
          <p className="profile-subtitle">Manage your profile and access key features</p>
        </div>
      </div>

      {/* Profile Content */}
      <div className="profile-content-section">
        {isLoading ? (
          <div className="modern-loading-container">
            <LoadingSpinner />
          </div>
        ) : profile ? (
          <div className="profile-grid">
            {/* Profile Card */}
            <div className="profile-card">
              <div className="profile-avatar-section">
                <div className="profile-avatar">
                  {profile.name ? profile.name.charAt(0).toUpperCase() : 
                   profile.username ? profile.username.charAt(0).toUpperCase() : 
                   profile.email ? profile.email.charAt(0).toUpperCase() : '?'}
                </div>
                <div className="profile-status">
                  <span className="status-badge active">Active</span>
                </div>
              </div>
              
              <div className="profile-details">
                {profile.name && (
                  <div className="profile-field">
                    <label className="field-label">Full Name</label>
                    <span className="field-value">{profile.name}</span>
                  </div>
                )}
                
                {profile.username && (
                  <div className="profile-field">
                    <label className="field-label">Username</label>
                    <span className="field-value">{profile.username}</span>
                  </div>
                )}
                
                {profile.email && (
                  <div className="profile-field">
                    <label className="field-label">Email</label>
                    <span className="field-value">{profile.email}</span>
                  </div>
                )}
                
                {profile.role && (
                  <div className="profile-field">
                    <label className="field-label">Role</label>
                    <span className="field-value role-badge">{profile.role}</span>
                  </div>
                )}
                
                {profile.department && (
                  <div className="profile-field">
                    <label className="field-label">Department</label>
                    <span className="field-value">{profile.department}</span>
                  </div>
                )}
                
                {profile.designation && (
                  <div className="profile-field">
                    <label className="field-label">Designation</label>
                    <span className="field-value">{profile.designation}</span>
                  </div>
                )}
                
                {profile.work_city && (
                  <div className="profile-field">
                    <label className="field-label">Work City</label>
                    <span className="field-value">{profile.work_city}</span>
                  </div>
                )}
                
                {profile.employee_id && (
                  <div className="profile-field">
                    <label className="field-label">Employee ID</label>
                    <span className="field-value">{profile.employee_id}</span>
                  </div>
                )}
              </div>
            </div>

            {/* Quick Actions Card */}
            <div className="quick-actions-card">
              <h3 className="actions-title">Quick Actions</h3>
              <div className="actions-grid">
                <button 
                  className="action-button primary"
                  onClick={goToEnhancedUpload}
                >
                  <span className="action-icon">📄</span>
                  <span className="action-text">Upload Bill</span>
                </button>
                
                <button 
                  className="action-button secondary"
                  onClick={() => navigate('/budget')}
                >
                  <span className="action-icon">🧳</span>
                  <span className="action-text">Trip Budget</span>
                </button>
                
                <button 
                  className="action-button secondary"
                  onClick={() => navigate('/profile')}
                >
                  <span className="action-icon">⚙️</span>
                  <span className="action-text">Settings</span>
                </button>
                
                <button 
                  className="action-button danger"
                  onClick={logout}
                >
                  <span className="action-icon">🚪</span>
                  <span className="action-text">Logout</span>
                </button>
              </div>
            </div>
          </div>
        ) : (
          <div className="error-container">
            <div className="error-icon">⚠️</div>
            <h3 className="error-title">Profile Not Found</h3>
            <p className="error-message">Unable to load profile information. Please try again.</p>
            <button className="retry-button" onClick={fetchProfile}>
              Retry
            </button>
          </div>
        )}
      </div>

      {/* Message Display */}
      {message && (
        <div className="modern-message error">
          <div className="message-content">
            <span className="message-icon">⚠️</span>
            <span className="message-text">{message}</span>
          </div>
        </div>
      )}
    </div>
  );
}

export default ProfilePage;
